package com.medcore.backend.api.enfermeria;import jakarta.persistence.*;import java.time.*;
@Entity@Table(name="observaciones_enfermeria")public class Observacion{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="internacion_id",nullable=false)private Long internacionId;@Column(name="enfermero_id",nullable=false)private Long enfermeroId;@Column(name="fecha_hora",nullable=false)private LocalDateTime fechaHora;@Column(nullable=false,length=3000)private String descripcion;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private TipoObservacion tipo;@Column(nullable=false,length=100)private String autor;
@PrePersist void init(){if(fechaHora==null)fechaHora=LocalDateTime.now(ZoneId.of("America/Argentina/Buenos_Aires"));}public Long getId(){return id;}public void setId(Long v){id=v;}public Long getInternacionId(){return internacionId;}public void setInternacionId(Long v){internacionId=v;}public Long getEnfermeroId(){return enfermeroId;}public void setEnfermeroId(Long v){enfermeroId=v;}public LocalDateTime getFechaHora(){return fechaHora;}public void setFechaHora(LocalDateTime v){fechaHora=v;}public String getDescripcion(){return descripcion;}public void setDescripcion(String v){descripcion=v;}public TipoObservacion getTipo(){return tipo;}public void setTipo(TipoObservacion v){tipo=v;}public String getAutor(){return autor;}public void setAutor(String v){autor=v;}}
